/**
 * Notion Node - Version 2
 * Discriminator: resource=databasePage, operation=get
 */


interface Credentials {
  notionApi: CredentialReference;
  notionOAuth2Api: CredentialReference;
}

/** Get a database */
export type NotionV2DatabasePageGetParams = {
  resource: 'databasePage';
  operation: 'get';
  authentication?: 'apiKey' | 'oAuth2' | Expression<string>;
/**
 * The Notion Database Page to get
 * @default {"mode":"url","value":""}
 */
    pageId?: { __rl: true; mode: 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @builderHint When true, v1 returns id and properties under their original names, such as $json.Status. In v2, database pages return id, name, url, and property_ keys with snake_case names, such as $json.property_status. V2 replaces non-ASCII characters with separators before converting names. Rich-text values are strings. Status values use the status name when present. People values are arrays of email addresses, with {} for missing emails. Match expressions and verification output fixtures to the node version. When false, read the native properties object, including people entries when you need person names.
 * @default true
 */
    simple?: boolean | Expression<boolean>;
};

export type NotionV2DatabasePageGetOutput = {
  id?: string;
  name?: string;
  url?: string;
};

export type NotionV2DatabasePageGetNode = {
  type: 'n8n-nodes-base.notion';
  version: 2;
  config: NodeConfig<NotionV2DatabasePageGetParams> & { credentials?: Credentials };
  output?: Items<NotionV2DatabasePageGetOutput>;
};